INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (123701, 166, "", "読書、魔法", "オタク全開な魔法少女", "O", 55, "ナナカ（ハロウィン）", 18, "トワイライトキャラバン", 13, "魔族", 0, 8, 21, "佳村はるか");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (123801, 165, "", "強敵との闘争", "傍若無人な王宮騎士団副団長", "O", "??", "クリスティーナ（ワイルド）", 27, "王宮騎士団（NIGHTMARE）", 8, "ヒューマン", 0, 2, 7, "たかはし智秋");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (123901, 146, "", "ヒーローごっこ", "ヒーローに憧れる騎士見習いの少女", "O", 40, "マツリ（ワイルド）", 12, "王宮騎士団（NIGHTMARE）", 8, "獣人族", 0, 11, 25, "下田麻美");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (124001, 150, "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "サックス", "甘え上手なみんなの人気者", "O", 42, "アカリ（クリスマス）", 13, "悪魔偽王国軍（ディアボロス）", 7, "魔族", 0, 11, 22, "浅倉杏美");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (124101, 150, "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", "ゲーム全般", "人見知りであまのじゃくな女の子", "O", 40, "ヨリ（クリスマス）", 13, "悪魔偽王国軍（ディアボロス）", 7, "魔族", 0, 11, 22, "原紗友里");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (124201, 171, "", "格闘技、湯浴み", "素顔を見せない冷静沈着な女性騎士", "A", 50, "ジュン（クリスマス）", 25, "王宮騎士団（NIGHTMARE）", 8, "ヒューマン", 0, 10, 25, "川澄綾子");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (124501, 168, "", "絵画、読書", "妖しい微笑で全てを見透かす臥竜の頭領", "O", "???", "ホマレ（ニューイヤー）", 25, "ドラゴンズネスト", 17, "ドラゴン族", 0, 4, 17, "大西沙織");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (124601, 165, "", "絵本作り", "母性溢れる優しいみんなの「ミサト先生」", "O", 54, "ミサト（ニューイヤー）", 21, "フォレスティエ", 6, "エルフ", 0, 9, 5, "國府田マリ子");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (124701, 166, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "研究、実験", "実験が趣味の危険な科学者", "A", 53, "ミツキ（ニューイヤー）", 27, "トワイライトキャラバン", 13, "ヒューマン", 0, 3, 7, "三石琴乃");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (124801, 157, "", "舞台鑑賞、ダンス", "歌って踊れる大人気アイドル", "B", 40, "ノゾミ（リベレイター）", 17, "カルミナ", 4, "ヒューマン", 0, 1, 24, "日笠陽子");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (124901, 156, "", "格闘技", "拳で語る喧嘩屋ドラゴン少女", "B", "???", "カヤ（リベレイター）", 16, "ドラゴンズネスト", 17, "ドラゴン族", 0, 6, 25, "小市眞琴");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (125001, 148, "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", "冒険、思い出話", "さまよえる謎の少女", "O", 40, "ムイミ（リベレイター）", 16, "？？？", "", "ヒューマン", 0, 8, 11, "潘めぐみ");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (125101, 158, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "猫とたわむれること", "弱きを助け強きをくじく猫娘", "AB", 48, "タマキ（カフェ）", 19, "メルクリウス財団", 12, "獣人族", 0, 3, 1, "沼倉愛美");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (125201, 140, "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "お菓子屋通い", "見た目も中身もお子ちゃまな異国の軍人", "A", 33, "モニカ（カフェ）", 17, "ヴァイスフリューゲル　ランドソル支部", 15, "ヒューマン", 0, 7, 28, "辻あゆみ");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (125301, 140, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "瞑想、動植物の飼育", "主を慕う、小さなガイド役", "B", 35, "コッコロ（レンジャー）", 11, "美食殿", 1, "エルフ", 0, 5, 11, "伊藤美来");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (125401, 153, "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", "読書、お散歩", "読書が趣味の病弱少女", "A", 40, "シオリ（レンジャー）", 14, "牧場（エリザベスパーク）", 11, "獣人族", 0, 11, 3, "小清水亜美");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (125501, 156, "", "冒険、おしゃべり", "空への冒険を夢見る騎空士の少女", "O", 45, "ジータ（ウォーロック）", 17, "？？？", "", "ヒューマン", 0, 3, 10, "金元寿子");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (125601, 145, "", "ネズ耳作り", "陰陽合わせ持つ鼠神宮の巫女", "AB", 39, "ビカラ", 14, "？？？", "", "ヒューマン", 0, 12, 4, "種﨑敦美");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (125701, 152, "", "書類仕事、散歩、ボードゲーム", "【ギルド管理協会】職員の親切なお姉さん", "A", 43, "カリン（アルケミスト）", 24, "？？？", "", "ヒューマン", 0, 9, 12, "洲崎綾");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (125801, 154, "", "華道、読書（古典）、トーゴク画", "贖罪を胸に強さを求める妹系大和撫子", "A", 44, "リリ（フォールン）", 15, "アルターメイデン", 20, "ヒューマン", 0, 4, 29, "鈴木みのり");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (126001, 147, "", "お菓子作り、花の世話、バイオリン演奏", "忘れ難い罪過を抱える、黒き翼の聖女", "O", 42, "クリア（フォールン）", 13, "アルターメイデン", 20, "ヒューマン", 0, 11, 1, "前田佳織里");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (126101, 135, "", "ごはんをたべること", "正義の魂を受け継ぐ、爆食系天然天才娘", "O", 34, "プレシア（フォールン）", 10, "アルターメイデン", 20, "獣人族", 0, 3, 1, "高尾奏音");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (126201, 172, "", "世界征服", "かつては夜を支配した最強の吸血鬼", "A", 50, "イリヤ（儀装束）", "??", "悪魔偽王国軍（ディアボロス）", 7, "魔族", 0, 5, 5, "丹下桜");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (126301, 150, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "鏡で自分を見ること", "ボクは誰よりも美しい", "AB", 40, "ユキ（儀装束）", 14, "ヴァイスフリューゲル　ランドソル支部", 15, "エルフ", 0, 10, 10, "大空直美");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (126401, 170, "", "昼寝、誰かの役に立つこと", "スマイル満タン！　パワフル機械少女", "?", "全重量252", "クローチェ", "??", "？？？", "", "機械人族", 0, 11, 11, "長谷川育美");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (126501, 162, "", "昼寝、新作スイーツの試食", "優しさと傲慢さを併せ持つプリンセス", "?", "??", "ライラエル", "??", "？？？", "", "天使族", 0, 1, 17, "河瀬茉希");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (126601, 149, "", "物真似、芸術鑑賞", "研究所に隠れ住む物静かなお姉さん", "O", "??", "ネネカ（サマー）", 24, "？？？", "", "エルフ", 0, 3, 24, "井口裕香");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (126701, 157, "この私とともにいる限り、\nお金に不自由はさせませんわ！", "慈善事業", "一人前の商人を目指すパワフルお嬢様", "AB", 45, "アキノ（サマー）", 18, "メルクリウス財団", 12, "ヒューマン", 0, 3, 12, "松嵜麗");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (126801, 164, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "ウインドーショッピング", "純情でほっとけない大人の女性", "A", 55, "ユカリ（サマー）", 22, "メルクリウス財団", 12, "エルフ", 0, 3, 16, "今井麻美");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (126901, 165, "", "歌、読書、詩を書くこと", "静寂を求め歌う陰気少女", "O", 53, "ランファ（サマー）", 20, "レイジ・レギオン", 19, "魔族", 0, 12, 28, "原田彩楓");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (127001, 157, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "小説を読むこと", "妄想大好き！　ほんとは照れ屋な女の子", "AB", 49, "クウカ（サマー）", 18, "ヴァイスフリューゲル　ランドソル支部", 15, "ヒューマン", 0, 11, 19, "長妻樹里");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (127101, 157, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "占い", "占いが得意な霊能少女", "AB", 42, "シノブ（サマー）", 18, "悪魔偽王国軍（ディアボロス）", 7, "魔族", 0, 12, 22, "大坪由佳");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (127201, 152, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "猫と遊ぶ", "行き倒れの謎のネコミミ魔法使い", "A", 39, "キャル（編入生）", 14, "美食殿", 1, "獣人族", 0, 9, 2, "立花理香");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (127301, 167, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "ファッション", "天真爛漫で人気者のカリスマモデル", "O", 48, "スズナ（編入生）", 17, "ルーセント学院", 14, "魔族", 0, 4, 10, "上坂すみれ");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (127501, 156, "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "経営、お茶会", "救護院を経営する優しい庶民派お嬢様", "A", 43, "サレン（サラサリア）", 17, "サレンディア救護院", 9, "エルフ", 0, 10, 4, "堀江由衣");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (127601, 167, "", "釣り", "人情味溢れる粋でいなせな「姉御」", "B", 54, "ルカ（サラサリア）", 25, "トワイライトキャラバン", 13, "ヒューマン", 0, 7, 11, "佐藤利奈");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (127701, 145, "", "妹と過ごす休日", "真面目で一生懸命なドラゴンメイド（姉）", "?", "???", "リンド", 12, "？？？", "", "ドラゴン族", 0, 2, 5, "豊田萌絵");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (127801, 145, "", "サボり、姉と過ごす休日", "不真面目で気怠げなドラゴンメイド（妹）", "?", "???", "ヴルム", 12, "？？？", "", "ドラゴン族", 0, 2, 5, "関根明良");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (127901, 156, "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "食べ歩き、料理", "いつも元気な腹ペコ少女", "O", 46, "ペコリーヌ（クリスマス）", 17, "美食殿", 1, "ヒューマン", 0, 3, 31, "M・A・O");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (128001, 160, "", "お金を数えること、悪だくみ", "忠義に目覚めた女商人", "A", 57, "クレジッタ（クリスマス）", 26, "リッチモンド商工会", 18, "ヒューマン", 0, 9, 19, "Lynn");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (128301, 145, "", "ゲーム", "口が達者なヘタレドラゴン", "AB", "???", "イノリ（ニューイヤー）", 13, "ドラゴンズネスト", 17, "ドラゴン族", 0, 9, 29, "藤田茜");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (128401, 156, "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", "妹と遊ぶこと、二度寝、昼寝、早寝", "みんなのために超能力を使う眠り姫", "A", 46, "ハツネ（ニューイヤー）", 17, "フォレスティエ", 6, "エルフ", 0, 12, 24, "大橋彩香");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (128501, 152, "", "読書、推理", "頭脳明晰な美少女名探偵", "AB", 41, "カスミ（ニューイヤー）", 15, "自警団（カォン）", 10, "獣人族", 0, 11, 3, "水瀬いのり");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (128701, 155, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助け、応援", "人助けが大好き！　前向き格闘娘", "A", 44, "ヒヨリ（アストラル）", 16, "トゥインクルウィッシュ", 2, "獣人族", 0, 8, 27, "東山奈央");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (128801, 163, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "読書、乗馬、お茶", "クールで何事にも真っ直ぐな剣士", "B", 46, "レイ（アストラル）", 18, "トゥインクルウィッシュ", 2, "魔族", 0, 1, 12, "早見沙織");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (128901, 158, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "料理、人間観察", "戦闘のサポートが得意な、心優しい少女", "O", 47, "ユイ（アストラル）", 17, "トゥインクルウィッシュ", 2, "ヒューマン", 0, 4, 5, "種田梨沙");
