INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (129901, 154, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "実験、裁縫、料理", "運命の相手に一途すぎる乙女", "B", 43, "エリコ（コマンダー）", 16, "トワイライトキャラバン", 13, "魔族", 0, 7, 30, "橋本ちなみ");
