INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (133501, 156, "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "経営、お茶会", "救護院を経営する優しい庶民派お嬢様", "A", 43, "サレン（ニューイヤー）", 17, "サレンディア救護院", 9, "エルフ", 0, 10, 4, "堀江由衣");
