INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (135701, 155, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助け、応援", "人助けが大好き！　前向き格闘娘", "A", 44, "ヒヨリ（サラサリア）", 16, "トゥインクルウィッシュ", 2, "獣人族", 0, 8, 27, "東山奈央");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (135801, 179, "", "三味線、死魔エナガのお世話", "真白き冬化粧を纏う、一途な心の雪女", "O", 63, "ユキノ", 19, "？？？", "", "雪女", 0, 12, 30, "天野聡美");
