INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (136301, 159, "", "特に無し", "明朗快活、なれど破滅に流るる溌溂少女", "A", "??", "ミソラ（クリスマス）", 16, "レイジ・レギオン", 19, "ヒューマン", 0, 7, 2, "鬼頭明里");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (136401, 158, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "料理、人間観察", "戦闘のサポートが得意な、心優しい少女", "O", 47, "ユイ（クリスマス）", 17, "トゥインクルウィッシュ", 2, "ヒューマン", 0, 4, 5, "種田梨沙");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (136501, 168, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "家事全般", "お姉ちゃんがお世話してあげるからねっ！", "O", 54, "シズル（ニューイヤー）", 18, "ラビリンス", 3, "ヒューマン", 0, 10, 24, "生天目仁美");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (136901, 148, "", "タコ料理、潮干狩り、ひとりじゃんけん", "がんばりましゅ！　うじゅうじゅタコ娘", "青", "??", "ルルィ", "13(?)", "？？？", "", "？？？", 0, 10, 8, "飯田ヒカル");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (137101, 163, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "忍法開発", "トーゴクの神秘、オシエテクダサイ！", "O", 51, "ニノン（サマー）", 16, "ヴァイスフリューゲル　ランドソル支部", 15, "ヒューマン", 0, 8, 31, "佐藤聡美");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (137401, 152, "", "読書、推理", "頭脳明晰な美少女名探偵", "AB", 41, "カスミ（シスター）", 15, "自警団（カォン）", 10, "獣人族", 0, 11, 3, "水瀬いのり");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (137601, 164, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "瞑想、動植物の飼育", "主を想い、“進化”したガイド役", "B", 48, "コッコロ（嚮導幼君）", 11, "美食殿", 1, "エルフ", 0, 5, 11, "伊藤美来");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (137901, 156, "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "お裁縫", "人懐っこくてマシンガントークな妹系少女", "A", 44, "リノ（ニューイヤー）", 15, "ラビリンス", 3, "ヒューマン", 0, 8, 25, "阿澄佳奈");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (138001, 158, "", "香水集め、物語を読むこと", "冥府に咲くアンデッド系プリンセス", "A", 49, "ヴァイオレット（イサナミ）", 17, "？？？", "", "ヒューマン", 0, 2, 21, "長縄まりあ");
