INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (138301, 156, "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "食べ歩き、料理", "いつも元気な腹ペコ少女", "O", 46, "ペコリーヌ（アストライア）", 17, "美食殿", 1, "ヒューマン", 0, 3, 31, "M・A・O");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (138701, 158, "", "編み物", "大変だけど元気です。盗賊ギルドの次女", "A", 45, "ワカナ（ウィンター）", 16, "バンディ・シスターズ", 21, "ヒューマン", 0, 5, 30, "石見舞菜香");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (138801, 153, "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", "読書、お散歩", "読書が趣味の病弱少女", "A", 40, "シオリ（ウィンター）", 14, "牧場（エリザベスパーク）", 11, "獣人族", 0, 11, 3, "小清水亜美");
