INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (139101, 152, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "猫と遊ぶ", "行き倒れの謎のネコミミ魔法使い", "A", 39, "キャル（覇瞳天星）", 14, "美食殿", 1, "獣人族", 0, 9, 2, "立花理香");
