INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (140101, 136, "", "ワカナをいぢめること", "生意気だけど超天才！　盗賊ギルドの三女", "AB", 37, "フブキ（サマー）", 12, "バンディ・シスターズ", 21, "獣人族", 0, 3, 5, "花井美春");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (180101, 155, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助け、応援", "人助けが大好き！　前向き格闘娘", "A", 44, "ヒヨリ（プリンセス）", 16, "トゥインクルウィッシュ", 2, "獣人族", 0, 8, 27, "東山奈央");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (180201, 158, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "料理、人間観察", "戦闘のサポートが得意な、心優しい少女", "O", 47, "ユイ（プリンセス）", 17, "トゥインクルウィッシュ", 2, "ヒューマン", 0, 4, 5, "種田梨沙");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (180301, 163, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "読書、乗馬、お茶", "クールで何事にも真っ直ぐな剣士", "B", 46, "レイ（プリンセス）", 18, "トゥインクルウィッシュ", 2, "魔族", 0, 1, 12, "早見沙織");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (180401, 156, "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "食べ歩き、料理", "いつも元気な腹ペコ少女", "O", 46, "ぺコリーヌ（プリンセス）", 17, "美食殿", 1, "ヒューマン", 0, 3, 31, "M・A・O");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (180501, 140, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "瞑想、動植物の飼育", "主を慕う、小さなガイド役", "B", 35, "コッコロ（プリンセス）", 11, "美食殿", 1, "エルフ", 0, 5, 11, "伊藤美来");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (180601, 152, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "猫と遊ぶ", "行き倒れの謎のネコミミ魔法使い", "A", 39, "キャル（プリンセス）", 14, "美食殿", 1, "獣人族", 0, 9, 2, "立花理香");
